import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const CLI_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const GENERATED = ['templates', 'hud', 'core', '_AGENTS.md'];

/**
 * Removes the artifacts generated by the prepack script.
 * @returns {void}
 */
function postpack() {
  GENERATED.forEach((name) => {
    fs.rmSync(path.join(CLI_ROOT, name), { recursive: true, force: true });
  });
}

postpack();
